(()=>{const cfg=window.SOURCEPILOT_CONFIG||{};const measurementId=String(cfg.ga4MeasurementId||'').trim();const CONSENT_KEY='buyerpilot_analytics_consent_v1';let loaded=false;let listenersAttached=false;function getChoice(){try{return localStorage.getItem(CONSENT_KEY)||'';}catch(_){return '';}}function setChoice(value){try{localStorage.setItem(CONSENT_KEY,value);}catch(_){}}function safePageLocation(){return `${location.origin}${location.pathname}${location.hash || ''}`;}function attachEvents(){if(listenersAttached)return;listenersAttached=true;const send=(name,params={})=>{try{window.gtag?.('event',name,params);}catch(_){}};document.addEventListener('click',(event)=>{const link=event.target.closest('a');if(!link)return;const href=link.getAttribute('href')||'';const checkout=link.getAttribute('data-checkout');const store=link.getAttribute('data-browser-store');if(checkout){send('buyerpilot_cta_click',{cta_type:'checkout_or_trial',plan:checkout,link_url:link.href||href});}if(store||/chromewebstore\.google\.com|microsoftedge\.microsoft\.com\/addons|addons\.mozilla\.org/i.test(href)){send('extension_store_click',{store:store||(/chromewebstore/i.test(href)?'chrome':/microsoftedge/i.test(href)?'edge':'firefox'),link_url:link.href||href});}if(/^mailto:/i.test(href)||/wa\.me|t\.me/i.test(href)){send('support_contact_click',{channel:/^mailto:/i.test(href)?'email':/t\.me/i.test(href)?'telegram':'whatsapp'});}});document.addEventListener('play',(event)=>{const video=event.target;if(!(video instanceof HTMLVideoElement))return;const source=video.currentSrc||video.querySelector('source')?.src||'';send('tutorial_video_play',{video_file:source.split('/').pop()||'video'});},true);}function loadAnalytics(){if(loaded||!/^G-[A-Z0-9]+$/i.test(measurementId))return;loaded=true;window.dataLayer=window.dataLayer||[];window.gtag=window.gtag||function(){window.dataLayer.push(arguments);};window.gtag('js',new Date());window.gtag('config',measurementId,{page_location:safePageLocation()});const tag=document.createElement('script');tag.async=true;tag.src=`https://www.googletagmanager.com/gtag/js?id=${encodeURIComponent(measurementId)}`;document.head.appendChild(tag);attachEvents();}function removeBanner(){document.querySelector('[data-buyerpilot-analytics-banner]')?.remove();}function showBanner(){if(document.querySelector('[data-buyerpilot-analytics-banner]'))return;const box=document.createElement('div');box.setAttribute('data-buyerpilot-analytics-banner','');box.setAttribute('role','dialog');box.setAttribute('aria-label','Analytics privacy choice');box.innerHTML=`
      <div style="font-weight:800;margin-bottom:5px">Privacy choice</div>
      <div style="font-size:13px;line-height:1.45;color:#c7d3e8">BuyerPilot uses optional Google Analytics to understand website usage. Essential website features work without it. <a href="privacy.html" style="color:#9db6ff">Privacy Policy</a></div>
      <div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:11px">
        <button type="button" data-bp-analytics-allow style="border:0;border-radius:9px;padding:9px 12px;background:#315efb;color:white;font-weight:700;cursor:pointer">Allow analytics</button>
        <button type="button" data-bp-analytics-deny style="border:1px solid #40516c;border-radius:9px;padding:9px 12px;background:#142238;color:white;font-weight:700;cursor:pointer">Essential only</button>
      </div>`;Object.assign(box.style,{position:'fixed',left:'16px',bottom:'16px',zIndex:'2147482999',width:'min(520px, calc(100vw - 32px))',padding:'15px',background:'#0d1a2c',color:'#fff',border:'1px solid #2d4161',borderRadius:'14px',boxShadow:'0 14px 38px rgba(0,0,0,.34)',fontFamily:'Inter, Arial, sans-serif'});box.querySelector('[data-bp-analytics-allow]').addEventListener('click',()=>{setChoice('granted');removeBanner();loadAnalytics();});box.querySelector('[data-bp-analytics-deny]').addEventListener('click',()=>{setChoice('denied');removeBanner();});document.body.appendChild(box);}function resetChoice(event){event?.preventDefault?.();try{localStorage.removeItem(CONSENT_KEY);}catch(_){}removeBanner();showBanner();}window.BuyerPilotPrivacy=Object.assign(window.BuyerPilotPrivacy||{},{resetAnalyticsChoice:resetChoice});const boot=()=>{document.querySelectorAll('[data-analytics-reset]').forEach((el)=>el.addEventListener('click',resetChoice));const choice=getChoice();if(choice==='granted')loadAnalytics();else if(choice!=='denied')showBanner();};if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot,{once:true});else boot();})();
